const render = () => {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  // planet
  ctx.fillStyle = '#555';
  ctx.beginPath();
  ctx.arc(center.x, center.y, planetRadius, 0, Math.PI * 2);
  ctx.fill();

  // ship
  const shipX = center.x + Math.cos(shipAngle) * shipOrbit;
  const shipY = center.y + Math.sin(shipAngle) * shipOrbit;
  ctx.fillStyle = '#0f0';
  ctx.beginPath();
  ctx.arc(shipX, shipY, shipRadius, 0, Math.PI * 2);
  ctx.fill();

  // bullets
  ctx.fillStyle = '#ff0';
  bullets.forEach(b => {
    ctx.beginPath();
    ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
    ctx.fill();
  });

  // asteroids
  ctx.fillStyle = '#f44';
  asteroids.forEach(a => {
    ctx.beginPath();
    ctx.arc(a.x, a.y, a.r, 0, Math.PI * 2);
    ctx.fill();
  });

  // score / game over text
  ctx.fillStyle = '#fff';
  ctx.font = '16px sans-serif';
  ctx.fillText('Score: ' + score, 10, 20);
  if (gameOver) {
    ctx.fillStyle = 'rgba(0,0,0,0.7)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#f00';
    ctx.textAlign = 'center';
    ctx.font = '32px sans-serif';
    ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
  }
};

